import React, { useState, useRef } from 'react';
import SmallButton from './SmallButton';

interface Model3DUploadProps {
  onModelUpload?: (file: File) => void;
  onCameraDataChange?: (cameraData: any) => void;
  initialModelUrl?: string;
  className?: string;
}

interface CameraData {
  orbit: {
    azimuth: number;
    polar: number;
    radius: number;
  };
  target: {
    x: number;
    y: number;
    z: number;
  };
  fieldOfView: number;
  zoomSpeed: number;
}

const Model3DUpload: React.FC<Model3DUploadProps> = ({
  onModelUpload,
  onCameraDataChange,
  initialModelUrl,
  className = ''
}) => {
  const [modelFile, setModelFile] = useState<File | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [error, setError] = useState<string>('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleModelFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      // Validate file type - only GLB files allowed
      const fileExtension = '.' + file.name.split('.').pop()?.toLowerCase();

      if (fileExtension !== '.glb') {
        setError('Please upload a valid GLB file (.glb only)');
        return;
      }

      // Validate file size (max 50MB)
      if (file.size > 50 * 1024 * 1024) {
        setError('File size must be less than 50MB');
        return;
      }

      setModelFile(file);
      setError('');

      // Create preview URL
      const url = URL.createObjectURL(file);
      setModelUrl(url);

      if (onModelUpload) {
        onModelUpload(file);
      }
    }
  };


  const handleUpload = async () => {
    if (!modelFile) {
      setError('Please select a 3D model file to upload');
      return;
    }

    setIsUploading(true);
    setUploadProgress(0);

    try {
      // Simulate upload progress
      const progressInterval = setInterval(() => {
        setUploadProgress(prev => {
          if (prev >= 90) {
            clearInterval(progressInterval);
            return 90;
          }
          return prev + 10;
        });
      }, 200);

      // Here you would typically upload to your server
      // For now, we'll just simulate the upload
      await new Promise(resolve => setTimeout(resolve, 2000));

      setUploadProgress(100);
      setError('');

      // Reset form
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
      setModelFile(null);

    } catch (err) {
      setError('Upload failed. Please try again.');
    } finally {
      setIsUploading(false);
    }
  };

  const handleCameraDataChange = (newCameraData: CameraData) => {
    setCameraData(newCameraData);
    if (onCameraDataChange) {
      onCameraDataChange(newCameraData);
    }
  };

  const handleSave = (cameraData: CameraData) => {
    console.log('Saving camera data:', cameraData);
    // Here you would save the camera data to your backend
  };

  const handleReset = () => {
    setCameraData({
      orbit: { azimuth: 0, polar: 75, radius: 3 },
      target: { x: 0, y: 1.6, z: 0 },
      fieldOfView: 45,
      zoomSpeed: 1.0
    });
  };

  const triggerFileInput = () => {
    fileInputRef.current?.click();
  };

  return (
    <div className={`model-3d-upload ${className}`}>
      {/* Upload Section */}
      <div className="container mt-4">
        <div className="row">
          {/* Left Column: Instructions */}
          <div className="col-md-6">
            <div className="card">
              <div className="card-body">
                <h5 className="subtext-btn mb-3">Upload a 3D Model</h5>
                <p className="subtext-btn-sm text-muted mb-3">
                  Upload a 3D model file (GLB format) for your season. This model will be used across all episodes in this season.
                </p>
                <div className="mb-3">
                  <h6 className="subtext-btn-sm mb-2">Requirements:</h6>
                  <ul className="subtext-btn-sm text-muted">
                    <li>File format: GLB only</li>
                    <li>Maximum file size: 50MB</li>
                    <li>Optimize your model for better performance</li>
                  </ul>
                </div>
                <div className="mt-4">
                  <small className="text-muted">
                    <i className="fas fa-info-circle me-1"></i>
                    The 3D model will be shared across all episodes in this season.
                  </small>
                </div>
              </div>
            </div>
          </div>

          {/* Right Column: Upload Form */}
          <div className="col-md-6">
            <div className="card">
              <div className="card-header">
                <h5 className="subtext-btn mb-0">3D Model Upload</h5>
              </div>
              <div className="card-body">
                <div className="mb-3">
                  <label htmlFor="modelFile" className="form-label subtext-btn-sm">
                    3D Model File (.glb only, max 50MB)
                  </label>
                  <input
                    ref={fileInputRef}
                    type="file"
                    className="form-control form-control-sm"
                    id="modelFile"
                    accept=".glb"
                    onChange={handleModelFileChange}
                    style={{ display: 'none' }}
                  />
                  <div className="d-flex gap-2">
                    <SmallButton 
                      variant="outline-primary" 
                      onClick={triggerFileInput}
                      disabled={isUploading}
                    >
                      <i className="fas fa-upload me-1"></i>
                      {modelFile ? 'Change Model' : ' Select Model'}
                    </SmallButton>
                    {modelFile && (
                      <SmallButton 
                        variant="success" 
                        onClick={handleUpload}
                        disabled={isUploading}
                      >
                        <i className="fas fa-cloud-upload-alt me-1"></i>
                        {isUploading ? 'Uploading...' : ' Upload'}
                      </SmallButton>
                    )}
                  </div>
                  {modelFile && (
                    <div className="mt-2">
                      <small className="text-muted subtext-btn-sm">
                        Selected: {modelFile.name} ({(modelFile.size / 1024 / 1024).toFixed(2)} MB)
                      </small>
                    </div>
                  )}
                </div>

                {isUploading && (
                  <div className="mb-3">
                    <div className="progress" style={{ height: '8px' }}>
                      <div 
                        className="progress-bar bg-success" 
                        role="progressbar" 
                        style={{ width: `${uploadProgress}%` }}
                      ></div>
                    </div>
                    <small className="text-muted subtext-btn-sm">
                      Uploading... {uploadProgress}%
                    </small>
                  </div>
                )}

                {error && (
                  <div className="alert alert-danger" role="alert">
                    <i className="fas fa-exclamation-triangle me-2"></i>
                    {error}
                  </div>
                )}

                <div className="mt-3">
                  <small className="text-muted">
                    <i className="fas fa-info-circle me-1"></i>
                    Maximum file size: 50MB (GLB files only)
                  </small>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Model3DUpload;
